        ['Prism binoculars use total internal reflection.', ['True', 'False'], 'A', '45° prisms.', 3, 'tf'],
        ['Light (speed 3 × 10⁸ m/s in vacuum) enters a medium of refractive index 1.25. Its speed in the medium is ___ × 10⁸ m/s.', ['2.4'], '', 'v = c ÷ n.', 3, 'fill'],
        ['Light (speed 3 × 10⁸ m/s in vacuum) enters a medium of refractive index 2. Its speed in the medium is ___ × 10⁸ m/s.', ['1.5'], '', 'v = c ÷ n.', 3, 'fill'],
        ['Light (speed 3 × 10⁸ m/s in vacuum) enters a medium of refractive index 1.2. Its speed in the medium is ___ × 10⁸ m/s.', ['2.5'], '', 'v = c ÷ n.', 3, 'fill'],
