    'SHS 2: Specific heat capacity and latent heat' => [
        ['Specific heat capacity is the heat needed to', ['raise the temperature of 1 kg of a substance by 1 K', 'melt 1 kg of a substance', 'raise any mass by 1 K', 'boil 1 kg of water'], 'A', 'Unit J kg⁻¹ K⁻¹.', 1],
        ['Heat capacity of a body is', ['the heat in 1 kg', 'the heat needed to raise its temperature by 1 K', 'its temperature', 'its mass'], 'B', 'Unit J/K; C = mc.', 2],
        ['Specific latent heat of fusion is the heat needed to', ['raise 1 kg by 1 K', 'boil 1 kg of liquid', 'change 1 kg of solid to liquid without a change in temperature', 'cool 1 kg'], 'C', 'At the melting point.', 2],
        ['Specific latent heat of vaporisation is the heat needed to', ['melt 1 kg of solid', 'raise 1 kg by 1 K', 'freeze 1 kg', 'change 1 kg of liquid to vapour without a change in temperature'], 'D', 'At the boiling point.', 2],
        ['During melting, the temperature of a pure solid', ['stays constant', 'rises steadily', 'falls', 'doubles'], 'A', 'Energy breaks bonds.', 1],
