        ['How much heat is needed to vaporise 2 kg of water at 100 °C? (L = 2.26 × 10⁶ J/kg)', ['4.52 × 10⁵ J', '6.72 × 10⁵ J', '4.52 × 10⁶ J', '1.13 × 10⁶ J'], 'C', 'Q = mL.', 2],
        ['How much heat is needed to raise 0.2 kg of a substance with c = 900 J kg⁻¹ K⁻¹ by 20 K?', ['180 J', '18,000 J', '360 J', '3,600 J'], 'D', 'Q = mcΔθ.', 2],
