        ['An echo is', ['a refracted sound', 'a diffracted sound', 'a reflected sound', 'an absorbed sound'], 'C', 'Heard after a delay.', 1],
        ['The audible frequency range for humans is about', ['0 Hz to 100 Hz', '1,000 Hz to 100,000 Hz', '20 kHz to 200 kHz', '20 Hz to 20,000 Hz'], 'D', 'Above 20 kHz is ultrasound.', 1],
        ['Ultrasound is used in', ['pre-natal scanning and sonar', 'radio broadcasting', 'X-ray photography', 'cooking food'], 'A', 'High-frequency sound.', 2],
        ['Resonance occurs when', ['a sound is reflected', 'a body is made to vibrate at its natural frequency', 'two sounds cancel', 'a body is at rest'], 'B', 'Large amplitude.', 2],
        ['For a closed pipe (resonance tube), the first resonance occurs at a length of about', ['λ/2', 'λ', 'λ/4', '2λ'], 'C', 'Node at the closed end.', 4],
