        ['A converging lens can form both real and virtual images.', ['True', 'False'], 'A', 'Depending on object position.', 2, 'tf'],
        ['A diverging lens has a positive power.', ['True', 'False'], 'B', 'Diverging lenses have negative power.', 2, 'tf'],
        ['The image on the retina is inverted.', ['True', 'False'], 'A', 'The brain interprets it upright.', 2, 'tf'],
        ['A slide projector forms a magnified, real image on a screen.', ['True', 'False'], 'A', 'Object between F and 2F.', 3, 'tf'],
        ['The near point of a normal eye is about 25 cm.', ['True', 'False'], 'A', 'Least distance of distinct vision.', 3, 'tf'],
        ['A magnifying glass uses a diverging lens.', ['True', 'False'], 'B', 'It uses a converging lens.', 1, 'tf'],
        ['A converging lens of focal length 40 cm has a power of ___ dioptres.', ['2.5'], '', 'P = 1 ÷ f(m).', 2, 'fill'],
        ['A converging lens of focal length 25 cm has a power of ___ dioptres.', ['4'], '', 'P = 1 ÷ f(m).', 2, 'fill'],
