        ['Moving a magnet into a coil induces a current.', ['True', 'False'], 'A', 'The flux linkage changes.', 1, 'tf'],
        ['A stationary magnet inside a coil induces a steady current.', ['True', 'False'], 'B', 'No change in flux, no induced e.m.f.', 2, 'tf'],
        ['Transformers can step up direct current.', ['True', 'False'], 'B', 'They need a.c.', 1, 'tf'],
        ['Faster movement of the magnet induces a larger e.m.f.', ['True', 'False'], 'A', 'Greater rate of change of flux.', 2, 'tf'],
        ['In an ideal transformer, power input equals power output.', ['True', 'False'], 'A', 'No energy losses.', 2, 'tf'],
        ['Eddy currents in the core heat up a transformer.', ['True', 'False'], 'A', 'Energy loss reduced by lamination.', 3, 'tf'],
        ['A transformer with 500 primary turns steps 240 V down to 120 V. The number of secondary turns is ___.', ['250'], '', 'Ns = Np × Vs ÷ Vp.', 3, 'fill'],
