    'SHS 3: Semiconductors, diodes and transistors' => [
        ['A semiconductor is a material whose conductivity is', ['higher than copper', 'between that of a conductor and an insulator', 'zero', 'always constant'], 'B', 'For example silicon and germanium.', 1],
