        ['Convection cannot take place in solids.', ['True', 'False'], 'A', 'Particles cannot move freely.', 1, 'tf'],
        ['Radiation needs a medium to travel through.', ['True', 'False'], 'B', 'It can travel through a vacuum.', 1, 'tf'],
