        ['Heat transfer through a vacuum takes place by ___.', ['radiation'], '', 'Electromagnetic waves.', 1, 'fill'],
        ['The movement of warm fluid upwards and cool fluid downwards is called a ___ current.', ['convection'], '', 'Fluids only.', 1, 'fill'],
        ['A material that conducts heat poorly is called an ___.', ['insulator', 'thermal insulator'], '', 'For example wood.', 1, 'fill'],
        ['Heat radiation is mainly in the ___ region of the electromagnetic spectrum.', ['infrared', 'infra-red'], '', 'Beyond red light.', 2, 'fill'],
