        ['Mixing red, green and blue light gives black.', ['True', 'False'], 'B', 'It gives white light.', 2, 'tf'],
        ['The order of the visible spectrum is remembered by the word ___.', ['ROYGBIV', 'roygbiv'], '', 'Red to violet.', 1, 'fill'],
        ['The splitting of white light into its colours is called ___.', ['dispersion'], '', 'By a prism.', 1, 'fill'],
        ['The electromagnetic waves used to sterilise surgical instruments and to treat cancer are ___ rays.', ['gamma', 'γ'], '', 'Very penetrating.', 2, 'fill'],
